import heapq


def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, revision_priority, tax_base):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_priority == "sequence_first":
            key = (sequence, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = raw if tax_base == "original" else net
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {}
    options = []
    for name in names:
        permitted = []
        for row in packages[name]:
            version = row["version"]
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            permitted.append(row)
        rows[name] = {r["version"]: r for r in permitted}
        options.append([-1] + sorted(rows[name]))

    roots = data["roots"]
    best = None
    best_key = None
    for vector in product(*options):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue

        edges = {}
        valid = True
        for name, version in selected.items():
            deps = []
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                depname = dep["name"]
                if depname not in selected or not dep["min"] <= selected[depname] <= dep["max"]:
                    valid = False
                    break
                deps.append(depname)
            edges[name] = deps
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(selected):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in selected):
            continue

        key = tuple(vector)
        if best_key is None or key < best_key:
            best_key = key
            best = selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for chosen in product((False, True), repeat=len(available)):
        selected = [job for job, take in zip(available, chosen) if take]
        if len(selected) != k:
            continue
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in selected)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    initial = (source, data["coupons"], initial_mask)
    distances = {initial: start}
    queue = [(start, source, data["coupons"], initial_mask)]
    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            normal = (depart + edge["duration"], remaining)
            choices = [normal]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((depart + duration, remaining - 1))
            next_node = edge["v"]
            next_mask = mask | bit.get(next_node, 0)
            for arrival, next_remaining in choices:
                if arrival > data["deadline"]:
                    continue
                next_state = (next_node, next_remaining, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_remaining, next_mask))
    return {"arrival": None}


